package com.retally.shared.ui.splash

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.graphics.ImageBitmap
import kotlin.io.encoding.Base64

/**
 * Mukesh's receipt-scan illustration with the emerald background keyed out to
 * transparent, embedded as base64 since binary resources can't be pushed to the
 * Mac from outside.
 */
@Composable
internal fun rememberSplashScanArt(): ImageBitmap {
    val bytes = remember { Base64.decode(SPLASH_SCAN_WEBP_B64) }
    return remember(bytes) { bytes.decodeImageBitmap() }
}

/** Platform decoder: BitmapFactory on Android, skia on iOS. */
internal expect fun ByteArray.decodeImageBitmap(): ImageBitmap

private const val SPLASH_SCAN_WEBP_B64 =
    ""